window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1b01b2e9ce332b4c"]={"versions": [{"id": "FIG-1b01b2e9ce332b4c", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Frame-Formatdiagramm (PDU-Bit-/Byte-Layout) für den AUTOSAR FlexRay Transport Layer (FrArTp). Das Diagramm spezifiziert die Struktur eines First Frame (FF) gemäß ISO 15765-2 innerhalb der Kommunikationsmatrix.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format gliedert sich in zwei Hauptbereiche:</p>\n<ul class=\"fig-list\">\n<li><strong>PCI (Protocol Control Information)</strong> mit einer Gesamtlänge von 2 Byte (16 Bit), unterteilt in:</li>\n<li><strong>FT (Frame Type)</strong>: 4 Bit zur Kennzeichnung des Frame-Typs (First Frame).</li>\n<li><strong>DL (Data Length)</strong>: 12 Bit zur Angabe der Gesamtlänge der zu übertragenden Nutzdatenbotschaft.</li>\n<li><strong>Data</strong>: Nutzdatenfeld mit variabler Länge („Length depending on configuration“), abhängig von der konfigurierten PDU-Größe des FlexRay-Clusters bzw. der FrArTp-Kanaldefinition.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der First Frame leitet eine segmentierte Botschaftsübertragung ein, wenn die Gesamtnutzlast die Kapazität eines einzelnen Single Frame überschreitet:</p>\n<ol class=\"fig-list\">\n<li>Der Sender kodiert den Frame-Typ (FT) und die Gesamtnutzdatenlänge (DL, bis zu 4095 Bytes über 12 Bit) im 2-Byte-PCI.</li>\n<li>Der verbleibende Raum der PDU wird mit dem ersten Datenfragment der Botschaft aufgefüllt.</li>\n<li>Nach Empfang des First Frame wertet die empfangende Instanz die DL aus, alloziert Puffer und initiiert die Flusssteuerung (Flow Control Frame) vor Übertragung nachfolgender Consecutive Frames.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende PDU-Feldaufteilung für ISO 15765-2-konforme First Frames im FrArTp. Entwickler von Treiber- und Stack-Implementierungen müssen sicherstellen, dass FT in den höchstwertigen 4 Bits und DL in den folgenden 12 Bits des 16-Bit-PCI serialisiert/deserialisiert werden (Big-Endian-Bitreihenfolge gemäß ISO 15765-2). Die Datenfeldlänge bestimmt sich dynamisch aus der konfigurierten FlexRay-PDU-Länge abzüglich der 2 Byte PCI.</p>"}, {"id": "FIG-787289afdd3c7b24", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Frame-Formatdiagramm (PDU-Bit-/Byte-Layout) für den AUTOSAR FlexRay Transport Layer (FrArTp). Das Diagramm spezifiziert die Struktur eines First Frame (FF) gemäß ISO 15765-2 innerhalb der Kommunikationsmatrix.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format gliedert sich in zwei Hauptbereiche:</p>\n<ul class=\"fig-list\">\n<li><strong>PCI (Protocol Control Information)</strong> mit einer Gesamtlänge von 2 Byte (16 Bit), unterteilt in:</li>\n<li><strong>FT (Frame Type)</strong>: 4 Bit zur Kennzeichnung des Frame-Typs (First Frame).</li>\n<li><strong>DL (Data Length)</strong>: 12 Bit zur Angabe der Gesamtlänge der zu übertragenden Nutzdatenbotschaft.</li>\n<li><strong>Data</strong>: Nutzdatenfeld mit variabler Länge („Length depending on configuration“), abhängig von der konfigurierten PDU-Größe des FlexRay-Clusters bzw. der FrArTp-Kanaldefinition.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der First Frame leitet eine segmentierte Botschaftsübertragung ein, wenn die Gesamtnutzlast die Kapazität eines einzelnen Single Frame überschreitet:</p>\n<ol class=\"fig-list\">\n<li>Der Sender kodiert den Frame-Typ (FT) und die Gesamtnutzdatenlänge (DL, bis zu 4095 Bytes über 12 Bit) im 2-Byte-PCI.</li>\n<li>Der verbleibende Raum der PDU wird mit dem ersten Datenfragment der Botschaft aufgefüllt.</li>\n<li>Nach Empfang des First Frame wertet die empfangende Instanz die DL aus, alloziert Puffer und initiiert die Flusssteuerung (Flow Control Frame) vor Übertragung nachfolgender Consecutive Frames.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende PDU-Feldaufteilung für ISO 15765-2-konforme First Frames im FrArTp. Entwickler von Treiber- und Stack-Implementierungen müssen sicherstellen, dass FT in den höchstwertigen 4 Bits und DL in den folgenden 12 Bits des 16-Bit-PCI serialisiert/deserialisiert werden (Big-Endian-Bitreihenfolge gemäß ISO 15765-2). Die Datenfeldlänge bestimmt sich dynamisch aus der konfigurierten FlexRay-PDU-Länge abzüglich der 2 Byte PCI.</p>"}], "trans": [{"from": "FIG-1b01b2e9ce332b4c", "to": "FIG-787289afdd3c7b24", "fr": "R3.2.3", "tr": "R4.0.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Am oberen Bildrand wurde die Dokumenttextzeile „The figure below shows the layout of a FF.“ fälschlicherweise in den Bildausschnitt mitgerendert.</li>\n<li>Das eigentliche Protokollformatdiagramm (Felder, Bitbreiten und Beschriftungen) ist unverändert.</li>\n</ul>"}]};
